function normalTexture(){const n=256,data=new Uint8Array(n*n*4),directions=[[3,5],[7,-3],[11,19],[23,13],[41,-37],[71,89]];for(let y=0;y<n;y++)for(let x=0;x<n;x++){let dx=0,dy=0;directions.forEach(([a,b],k)=>{const phase=(a*x+b*y)*2*Math.PI/n,weight=.26/(1+k*.45),length=Math.hypot(a,b);dx+=Math.cos(phase)*weight*a/length;dy+=Math.cos(phase)*weight*b/length;});const v=new T.Vector3(-dx,-dy,1).normalize(),i=(y*n+x)*4;data[i]=(v.x*.5+.5)*255;data[i+1]=(v.y*.5+.5)*255;data[i+2]=(v.z*.5+.5)*255;data[i+3]=255;}const t=new T.DataTexture(data,n,n);t.wrapS=t.wrapT=T.RepeatWrapping;t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;t.generateMipmaps=true;t.needsUpdate=true;return t;}

export function pelagic(){const scene=new T.Scene();scene.background=new T.Color('#749cac');scene.fog=new T.FogExp2('#749cac',.0016);lighting(scene,'#c4e4e6','#1e4651',1.6);const b=batch(scene),r=rng(122),m={stone:surface('stone','#aabdb7',.2),metal:surface('metal','#536e75',.68),edge:material('#d3dacf',.45,.3),dark:material('#233e49',.6,.4),light:glow('#b3efdf',1.2),sand:surface('stone','#536f68'),kelp:material('#195c4d',.05,.8),rock:surface('stone','#485b5d')};
 const sky=mesh(scene,new T.SphereGeometry(1700,32,24),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,uniforms:{time:{value:0}},vertexShader:'varying vec3 v;void main(){v=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:`varying vec3 v;uniform float time;float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+1.),f.x),f.y);}void main(){vec3 d=normalize(v);float h=max(d.y,0.);vec3 col=mix(vec3(.66,.78,.8),vec3(.12,.33,.48),pow(h,.45));vec2 p=d.xz/(h+.22)*2.;float n=noise(p)+noise(p*2.1)*.5+noise(p*4.3)*.25;float cloud=smoothstep(.74,1.24,n)*smoothstep(0.,.12,h)*.52;col=mix(col,vec3(.89,.9,.86),cloud);vec3 sun=normalize(vec3(-.45,.2,-.87));float s=max(dot(d,sun),0.);col+=vec3(1.,.8,.5)*pow(s,700.)*.9;col+=vec3(.3,.19,.08)*pow(s,20.);gl_FragColor=vec4(col,1.);}`}),[0,0,0]);
 const geometry=new T.PlaneGeometry(2600,2600,220,220);const positions=geometry.attributes.position;for(let i=0;i<positions.count;i++){for(let axis=0;axis<2;axis++){const v=axis===0?positions.getX(i):positions.getY(i),n=Math.sign(v)*Math.pow(Math.abs(v)/1300,2.1)*1300;if(axis===0)positions.setX(i,n);else positions.setY(i,n);}}geometry.computeVertexNormals();
 const water=new Water(geometry,{textureWidth:768,textureHeight:768,waterNormals:normalTexture(),sunDirection:new T.Vector3(-.45,.2,-.87).normalize(),sunColor:0xffedd0,waterColor:0x075a63,distortionScale:3.4,fog:true});water.rotation.x=-Math.PI/2;water.position.y=-.8;water.material.uniforms.size.value=6;
 water.material.vertexShader=water.material.vertexShader.replace('void main() {','void main() { vec3 wavePosition=position; wavePosition.z+=sin(position.x*.08+time*.45)*.65+sin(position.y*.12-time*.36)*.33+sin((position.x+position.y)*.041+time*.25)*.8;').replaceAll('vec4( position, 1.0 )','vec4( wavePosition, 1.0 )');
 water.material.fragmentShader=water.material.fragmentShader.replace('float rf0 = 0.3;','float rf0 = 0.035;').replace('vec3 surfaceNormal = normalize( noise.xzy * vec3( 1.5, 1.0, 1.5 ) );','vec3 surfaceNormal=normalize(vec3(-.052*cos(worldPosition.x*.08+time*.45)-.0328*cos((worldPosition.x-worldPosition.z)*.041+time*.25),1.,.0396*cos(-worldPosition.z*.12-time*.36)-.0328*cos((worldPosition.x-worldPosition.z)*.041+time*.25))+vec3(noise.x*.45,0.,noise.y*.45));').replace('vec3 outgoingLight = albedo;','float swell=sin(worldPosition.x*.08+time*.45)+sin(worldPosition.z*.12-time*.36)*.5;float crest=smoothstep(1.38,1.5,swell)*.08;vec3 outgoingLight=mix(albedo,vec3(.008,.105,.145),.3)+vec3(.45,.6,.59)*crest;');scene.add(water);
 // Retained arches now have segmented cladding, double structural ribs and tie rods.
 for(let k=0;k<3;k++){const cx=-16,cz=-14-k*12,rad=12.5-k*.5;for(let i=0;i<46;i++){const a=-.19+i/45*Math.PI*1.13,x=cx+Math.cos(a)*rad,y=1+Math.sin(a)*rad;b.round(m.stone,x,y,cz,1.15,.75,1.5,0,0,a+Math.PI/2);b.round(m.metal,x,y,cz-.85,1.23,.2,.15,0,0,a+Math.PI/2);b.round(m.metal,x,y,cz+.85,1.23,.2,.15,0,0,a+Math.PI/2);for(const s of [-1,1])b.cylinder(m.dark,x+s*.23,y,cz+.92,.09,.09,.09,Math.PI/2,0,0);if(i%4===0){b.round(m.light,cx+Math.cos(a)*(rad-.58),1+Math.sin(a)*(rad-.58),cz,.08,.24,.25,0,0,a+Math.PI/2);if(k<2)b.beam(m.metal,[x,y,cz],[x,y,cz-12],.09,true);}}
 }
 // A low observatory deck keeps the ocean and horizon dominant.
 b.round(m.metal,-16,.8,7,12,1.2,33);for(let i=0;i<36;i++){b.box(m.stone,-16,1.45,-9+i*.86,11.6,.12,.8);for(const x of [-21.6,-10.4])b.cylinder(m.dark,x,1.54,-9+i*.86,.055,.04,.055);}rail(b,m.edge,m.light,[-22,1.6,-10],[-22,1.6,23]);rail(b,m.edge,m.light,[-10,1.6,-10],[-10,1.6,23]);
 for(let x of [-21,-11])for(let z of [-5,5,17]){b.cylinder(m.metal,x,-9,z,.8,21,.8);for(let y=-17;y<0;y+=4)b.cylinder(m.stone,x,y,z,1.15,.5,1.15);}
 for(let i=0;i<9;i++){b.round(m.stone,-16,-1-i*.38,25+i*.5,5,.3,.5);b.beam(m.edge,[-19,-1-i*.38,25+i*.5],[-19,-1-(i+1)*.38,25+(i+1)*.5],.07,true);}
 b.round(m.dark,-16,-18,0,19,.7,30);for(let i=0;i<18;i++)b.box(m.stone,-16,-17.6,-13+i*1.5,18,.12,1.4);rail(b,m.edge,m.light,[-25,-17.5,-14],[-25,-17.5,14]);rail(b,m.edge,m.light,[-7,-17.5,-14],[-7,-17.5,14]);
 // Distant rocky islands and submerged ridges break up the empty horizon.
 function island(x,z,s,h){const g=new T.SphereGeometry(1,40,28),p=g.attributes.position;for(let i=0;i<p.count;i++){const xx=p.getX(i),yy=p.getY(i),zz=p.getZ(i),n=1+Math.sin(xx*15+zz*9)*.07+Math.sin(zz*24-yy*13)*.055;p.setXYZ(i,xx*s*n,yy*h*n,zz*s*.65*n);}g.computeVertexNormals();mesh(scene,g,m.rock,[x,-h*.2,z]);}
 island(125,-175,65,42);island(-130,-255,92,49);island(240,-370,125,60);island(-75,-80,18,12);
 const seabed=new T.PlaneGeometry(520,520,100,100),p=seabed.attributes.position;for(let i=0;i<p.count;i++)p.setZ(i,Math.sin(p.getX(i)*.035)*3+Math.cos(p.getY(i)*.052)*2+Math.sin((p.getX(i)+p.getY(i))*.08));seabed.computeVertexNormals();mesh(scene,seabed,m.sand,[0,-31,0],[-Math.PI/2,0,0]);
 const bedHeight=(x,z)=>-31+Math.sin(x*.035)*3+Math.cos(z*.052)*2+Math.sin((x-z)*.08);
 for(let i=0;i<95;i++){const x=(r()-.5)*200,z=(r()-.5)*200,s=1+r()*5;b.sphere(m.rock,x,bedHeight(x,z)+s*.17,z,s,s*.6,s*.7);}
 // Tapered, curved kelp blades rooted on the actual sea floor; no rigid rods.
 const bladePositions=[],bladeUV=[],bladeIndices=[];
 for(let plant=0;plant<210;plant++){const x=(r()-.5)*170,z=(r()-.5)*170,y=bedHeight(x,z),phase=r()*6.28;for(let blade=0;blade<4;blade++){const h=2+r()*6,w=.2+r()*.35,angle=phase+blade*1.57,start=bladePositions.length/3;for(let j=0;j<=16;j++){const v=j/16,cx=x+Math.sin(v*2.8+phase)*v*1.4+Math.cos(angle)*v,cz=z+Math.cos(v*2.2+phase)*v*1.2+Math.sin(angle)*v,width=w*Math.pow(Math.sin(v*Math.PI),.7)+.012;for(const side of [-1,1]){bladePositions.push(cx+Math.cos(angle)*width*side,y+v*h,cz+Math.sin(angle)*width*side);bladeUV.push(side===-1?0:1,v);}if(j<16){const a=start+j*2;bladeIndices.push(a,a+1,a+2,a+1,a+3,a+2);}}}}
 const bladeGeo=new T.BufferGeometry();bladeGeo.setAttribute('position',new T.Float32BufferAttribute(bladePositions,3));bladeGeo.setAttribute('uv',new T.Float32BufferAttribute(bladeUV,2));bladeGeo.setIndex(bladeIndices);bladeGeo.computeVertexNormals();const bladeMat=material('#285746',.02,.95);bladeMat.side=T.DoubleSide;const sway={value:0};bladeMat.onBeforeCompile=shader=>{shader.uniforms.swayTime=sway;shader.vertexShader='uniform float swayTime;\n'+shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntransformed.x+=sin(swayTime*.6+position.y*.5+position.z*.1)*uv.y*uv.y*.35;');};mesh(scene,bladeGeo,bladeMat);
 // Fusiform bodies and shaped tail/dorsal fins, instanced as a small school.
 const fish=new T.Group();scene.add(fish);const bodyGeo=new T.LatheGeometry([new T.Vector2(0,-.52),new T.Vector2(.045,-.37),new T.Vector2(.12,-.24),new T.Vector2(.17,0),new T.Vector2(.135,.24),new T.Vector2(.065,.4),new T.Vector2(0,.5)],20);bodyGeo.rotateZ(-Math.PI/2);
 const tailShape=new T.Shape();tailShape.moveTo(-.4,0);tailShape.lineTo(-.8,.24);tailShape.lineTo(-.7,0);tailShape.lineTo(-.8,-.24);tailShape.closePath();const tailGeo=new T.ShapeGeometry(tailShape);const dorsal=new T.Shape();dorsal.moveTo(-.21,.1);dorsal.lineTo(-.13,.3);dorsal.lineTo(.19,.13);dorsal.closePath();const dorsalGeo=new T.ShapeGeometry(dorsal);const parts=[bodyGeo,tailGeo,dorsalGeo].map(g=>g.toNonIndexed()),fishGeo=mergeGeometries(parts);parts.forEach(g=>g.dispose());bodyGeo.dispose();tailGeo.dispose();dorsalGeo.dispose();const silver=material('#7caaa4',.28,.55);silver.side=T.DoubleSide;const bodies=new T.InstancedMesh(fishGeo,silver,160),eyes=new T.InstancedMesh(new T.SphereGeometry(.021,7,5),material('#081e25'),320),dummy=new T.Object3D();for(let i=0;i<160;i++){dummy.position.set((r()-.5)*45,-12-r()*10,(r()-.5)*65);dummy.rotation.set(0,(r()-.5)*1.1,(r()-.5)*.15);dummy.scale.setScalar(.65+r()*.65);dummy.updateMatrix();bodies.setMatrixAt(i,dummy.matrix);for(const side of [-1,1])eyes.setMatrixAt(i*2+(side===1?1:0),dummy.matrix.clone().multiply(new T.Matrix4().makeTranslation(.32,.035,side*.095)));}fish.add(bodies,eyes);
 const particles=new T.BufferGeometry(),pp=[];for(let i=0;i<1000;i++)pp.push((r()-.5)*150,-2-r()*35,(r()-.5)*150);particles.setAttribute('position',new T.Float32BufferAttribute(pp,3));const motes=new T.Points(particles,new T.PointsMaterial({color:'#8ed5ce',size:.045,transparent:true,opacity:.6,depthWrite:false}));scene.add(motes);
 const ceiling=mesh(scene,new T.PlaneGeometry(1600,1600),new T.MeshBasicMaterial({color:'#568e98',side:T.DoubleSide,transparent:true,opacity:.6}),[0,-.5,0],[-Math.PI/2,0,0]);ceiling.visible=false;
 text(scene,'PELAGIC / 02',[-20,1.57,17],9,'#46636b',[-Math.PI/2,0,0],.9);b.finish();
 return{scene,portals:[],pose:{position:[43,18,68],target:[-6,1,-65]},caption:'OPEN OCEAN / TIDAL RESEARCH<br>SECTOR 02 — SWELL & DEPTH',animate(t,camera){water.material.uniforms.time.value=t;sway.value=t;const under=camera.position.y<-.7;water.visible=!under;sky.visible=!under;ceiling.visible=under;scene.fog.color.set(under?'#073f50':'#749cac');scene.fog.density=under?.013:.0016;scene.background.set(under?'#073f50':'#749cac');fish.position.x=Math.sin(t*.1)*12;fish.position.z=Math.cos(t*.07)*8;motes.rotation.y=t*.003;}};
}
